head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldbnf20100";
scwin.dmenus = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_bndMktactTpCd", fn: function () { return String(String((dma_pageContext.get("bndMktactTpCd") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_datefmt_cal_procsReqDd
 * @description 초기화 — datefmt cal procs Req Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_procsReqDd = function () { $c.date.checkCalendarFormat("cal_procsReqDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_datefmt_cal_rsnOccrDd
 * @description 초기화 — datefmt cal rsn Occr Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_rsnOccrDd = function () { $c.date.checkCalendarFormat("cal_rsnOccrDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.getBdchrgInfo($c.util.getComponent('slc_bdchrgTpCd'));

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf20100.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_searchIsuInfoChgList();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.dmenus ={
        "bmenu":3
        ,"mmenu":9
    }; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldbnf20100' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_datefmt_cal_procsReqDd();
        scwin.init_datefmt_cal_rsnOccrDd();
        await scwin.init_loadList();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf20100.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_mpd_files_select_onclick
 * @description 「파일선택」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_mpd_files_select_onclick = function () {
    try { $c.util.onUploadClick($c.util.getComponent('mpd_files'));
    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf20100.btn_mpd_files_select_onclick' }); }
};

/**
 * @method
 * @name btn_mpd_files_del_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_mpd_files_del_onclick = async function () {
    try { const d = $c.util.getComponent('dlt_files'); const g = $c.util.getComponent('grd_mpd_files'); const u = $c.util.getComponent('mpd_files'); if (!d || !g) { return; } const idx = g.getCheckedIndex ? g.getCheckedIndex('CHK') : []; if (!idx || !idx.length) { return; } for (let i = idx.length - 1; i >= 0; i--) { try { const nm = d.getCellData(idx[i], 'FILE_NM'); if (u && u.removeFile) { u.removeFile(nm); } } catch (_e) { await $c.exception.handleError(_e, { notify: 'none', context: 'mpd_files.del' }); } } if (d.removeRows) { d.removeRows(idx); }
    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf20100.btn_mpd_files_del_onclick' }); }
};

/**
 * @method
 * @name ipt_redmptAmt_onblur
 * @description ipt_redmptAmt 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_redmptAmt_onblur = async function(e){
    try {
        await scwin.calcListAmt();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf20100.ipt_redmptAmt_onblur' }); }
};

/**
 * @method
 * @name ipt_redmptAmt_onkeyup
 * @description ipt_redmptAmt 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_redmptAmt_onkeyup = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        $c.util.getComponent('txt_redmptAmtKor').setValue($c.num.formatNumberKor(String((((selfVar) && (selfVar).getValue) ? (selfVar).getValue() : ((((selfVar) && typeof (selfVar).val === 'function') ? (selfVar).val() : (((selfVar) && (selfVar).value !== undefined) ? (selfVar).value : (selfVar))))) == null ? '' : (((selfVar) && (selfVar).getValue) ? (selfVar).getValue() : ((((selfVar) && typeof (selfVar).val === 'function') ? (selfVar).val() : (((selfVar) && (selfVar).value !== undefined) ? (selfVar).value : (selfVar)))))).replace(/,/g, '')));

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf20100.ipt_redmptAmt_onkeyup' }); }
};

/**
 * @method
 * @name slc_bdchrgTpCd_onchange
 * @description slc_bdchrgTpCd 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_bdchrgTpCd_onchange = async function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        await scwin.getBdchrgInfo(selfVar)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf20100.slc_bdchrgTpCd_onchange' }); }
};

/**
 * @method
 * @name btn_fileBrowse_onclick
 * @description btn_fileBrowse 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_fileBrowse_onclick = function(e){
    try {
        $c.util.onUploadClick($c.util.getComponent('mpd_files'))

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf20100.btn_fileBrowse_onclick' }); }
};

/**
 * @method
 * @name btn_delRow_onclick
 * @description btn_delRow 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_delRow_onclick = function(e){
    try {
        fn_delRow()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf20100.btn_delRow_onclick' }); }
};

/**
 * @method
 * @name btn_save_onclick
 * @description btn_save 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_save_onclick = async function(e){
    try {
        await scwin.save()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf20100.btn_save_onclick' }); }
};

/**
 * @method
 * @name btn_searchIsuInfoChgList_onclick
 * @description btn_searchIsuInfoChgList 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_searchIsuInfoChgList_onclick = async function(e){
    try {
        await scwin.searchIsuInfoChgList()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf20100.btn_searchIsuInfoChgList_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_searchIsuInfoChgList
 * @description search Isu Info Chg List 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchIsuInfoChgList = async function (action) {
    const sbmOptions = {
        id: "tx_fn_searchIsuInfoChgList",
        method: "post",
        action: action ?? "/common/IsuInfoChgSearch.do?method=searchIsuInfoChgList",
        ref: "dma_searchIsuInfoChgListReq",
        target: "dlt_bdchrgTpCdList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_save
 * @description save 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_save = async function (action) {
    const sbmOptions = {
        id: "tx_fn_save",
        method: "post",
        action: action ?? "/amount/amount.do?method=saveMidRepayPart",
        ref: "dma_saveReq",
        target: "dlt_bdchrgTpCdList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_GetBdchrgInfo
 * @description Get Bdchrg Info 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_GetBdchrgInfo = async function () {
    const sbmOptions = {
        id: "tx_fn_GetBdchrgInfo",
        method: "post",
        action: "/account/userInfo.do?method=selectBdchrgDtlInfo",
        ref: "dma_GetBdchrgInfoReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name mpd_files_selectCallback
 * @description mpd files select Callback 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.mpd_files_selectCallback = function (data) { const d = $c.util.getComponent('dlt_files'); if (!d) { return; } const rows = []; for (let i = 0; i < (data || []).length; i++) { rows.push({ FILE_NM: data[i].name, FILE_SIZE: String(data[i].size), CHK: '' }); } if (rows.length) { d.insertJSON(d.getRowCount(), rows); } };

/**
 * @method
 * @name searchIsuInfoChgList
 * @description search Isu Info Chg List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchIsuInfoChgList = async function () {
    await scwin.tx_fn_searchIsuInfoChgList('/common/IsuInfoChgSearch.do?method=searchIsuInfoChgList');
};

/**
 * @method
 * @name calcListAmt
 * @description calc List Amt 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.calcListAmt = async function () {
    const redmptAmt = parseInt($c.util.getComponent('ipt_redmptAmt').getValue().replace(/\,/g, ''));
    const redmptPreListAmt = parseInt($c.util.getComponent('ipt_redmptPreListAmt').getValue().replace(/\,/g, ''));
    if (redmptPreListAmt < redmptAmt) {
        await $c.win.alert("중도상환금액을 확인하세요.");
        $c.util.getComponent("ipt_redmptAmt").focus();
        return;
    }
    const afchgListAmt = redmptPreListAmt - redmptAmt;
    if (afchgListAmt >= 0) {
        $c.util.getComponent("ipt_afchgListAmt").setValue($c.num.formatMoney(afchgListAmt + ''));
    }
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function () {
    if (!await scwin.checkData()) {
        return;
    } else {
        if (!await $c.win.confirm("신청하시겠습니까?")) {
            return false;
        }
    }
    await scwin.tx_fn_save('/amount/amount.do?method=saveMidRepayPart');
};

/**
 * @method
 * @name checkData
 * @description check Data 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkData = async function () {
    const _mktact_cd = $c.util.getComponent("dma_searchIsuInfoChgListReq").get("bndMktactTpCd");
    const _now_time = dma_hiddenStore.get("areaNowTimer");
    const _isur_cd = $c.util.getComponent("dma_searchIsuInfoChgListReq").get("isurCd");
    if (!applTmCheck(_mktact_cd, _now_time, _isur_cd)) {
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('cal_procsReqDd').getValue()) === 0) {
        await $c.win.alert("적용희망일을 입력하십시오.");
        $c.util.getComponent("cal_procsReqDd").focus();
        return false;
    }
    if (WebSquare.date.getCurrentServerDate("yyyyMMdd") >= $c.util.getComponent('cal_procsReqDd').getValue().replace("-", "").replace("-", "")) {
        await $c.win.alert("적용희망일은 익일 이후만 입력가능합니다.");
        $c.util.getComponent("cal_procsReqDd").focus();
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('cal_rsnOccrDd').getValue()) === 0) {
        await $c.win.alert("등록말소일을 입력하십시오.");
        $c.util.getComponent("cal_rsnOccrDd").focus();
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_redmptAmt').getValue()) === 0) {
        await $c.win.alert("중도상환금액을 입력하십시오.");
        $c.util.getComponent("ipt_redmptAmt").focus();
        return false;
    }
    if (!!!(($c.util.getComponent('dlt_files')) && ($c.util.getComponent('dlt_files')).getRowCount && ($c.util.getComponent('dlt_files')).getRowCount() > 0)) {
        return false;
    }
    if ($c.str.getByteLength($c.util.getComponent('slc_bdchrgTpCd').getValue()) === 0) {
        return false;
    }
    const totFileSize = (Math.round(((($c.util.getComponent('dlt_files')) && ($c.util.getComponent('dlt_files')).getRowCount) ? Array.from({ length: ($c.util.getComponent('dlt_files')).getRowCount() }, function (x, i) { return Number(($c.util.getComponent('dlt_files')).getCellData(i, 'FILE_SIZE')) || 0; }).reduce(function (a, b) { return a + b; }, 0) : 0) / (1024 * 1024) * 100) / 100);
    if (totFileSize > 100) {
        await $c.win.alert("전체 첨부파일의 크기는 최대 100MB까지 허용됩니다.\n현재 크기 = " + totFileSize + "MB");
        return false;
    }
    return true;
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    $c.util.getComponent("cal_procsReqDd").setValue("");
    $c.util.getComponent("cal_rsnOccrDd").setValue("");
    $c.util.getComponent("ipt_redmptAmt").setValue("");
    $c.util.getComponent("ipt_afchgListAmt").setValue("");
};

/**
 * @method
 * @name setTelNo
 * @description set Tel No 처리
 * @param {*} pTelNo pTelNo
 * @returns {void}
 * @hidden N
 */
scwin.setTelNo = function (pTelNo) {
    if (pTelNo != null && pTelNo !== '') {
        const pTelNoArr = pTelNo.split('-');
        if (pTelNoArr.length === 3) {
            if (pTelNoArr[0] === "00") {
                $c.util.getComponent('ipt_apctTelNo1').setValue("");
            } else {
                $c.util.getComponent('ipt_apctTelNo1').setValue(pTelNoArr[0]);
            }
            $c.util.getComponent('ipt_apctTelNo2').setValue(pTelNoArr[1]);
            $c.util.getComponent('ipt_apctTelNo3').setValue(pTelNoArr[2]);
        } else {

        }
    }
};

/**
 * @method
 * @name setCellphoneNo
 * @description set Cellphone No 처리
 * @param {*} pCellphoneNo pCellphoneNo
 * @returns {void}
 * @hidden N
 */
scwin.setCellphoneNo = function (pCellphoneNo) {
    if (pCellphoneNo != null && pCellphoneNo !== '') {
        const pCellphoneNoArr = pCellphoneNo.split('-');
        if (pCellphoneNoArr.length === 3) {
            $c.util.getComponent('ipt_encrypCellphoneNo1').setValue(pCellphoneNoArr[0]);
            $c.util.getComponent('ipt_encrypCellphoneNo2').setValue(pCellphoneNoArr[1]);
            $c.util.getComponent('ipt_encrypCellphoneNo3').setValue(pCellphoneNoArr[2]);
        } else {

        }
    }
};

/**
 * @method
 * @name setEmail
 * @description set Email 처리
 * @param {*} pEmail pEmail
 * @returns {void}
 * @hidden N
 */
scwin.setEmail = function (pEmail) {
    if (pEmail != null && pEmail !== '') {
        const pEmailArr = pEmail.split('@');
        if (pEmailArr.length === 2) {
            $c.util.getComponent('ipt_encrypApctEmail1').setValue(pEmailArr[0]);
            $c.util.getComponent('ipt_encrypApctEmail2').setValue(pEmailArr[1]);
        } else {

        }
    }
};

/**
 * @method
 * @name setFaxNo
 * @description set Fax No 처리
 * @param {*} pFaxNo pFaxNo
 * @returns {void}
 * @hidden N
 */
scwin.setFaxNo = function (pFaxNo) {
    if (pFaxNo != null && pFaxNo !== '') {
        const pFaxNoArr = pFaxNo.split('-');
        if (pFaxNoArr.length === 3) {
            if (pFaxNoArr[0] === "00") {
                $c.util.getComponent('ipt_apctFaxNo1').setValue("");
            } else {
                $c.util.getComponent('ipt_apctFaxNo1').setValue(pFaxNoArr[0]);
            }
            $c.util.getComponent('ipt_apctFaxNo2').setValue(pFaxNoArr[1]);
            $c.util.getComponent('ipt_apctFaxNo3').setValue(pFaxNoArr[2]);
        } else {

        }
    }
};

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name getBdchrgInfoDone
 * @description get Bdchrg Info Done 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.getBdchrgInfoDone = function (data) {
    const result = (typeof data === "string" ? JSON.parse(data) : data);
    $c.util.getComponent('ipt_chrgId').setValue(result.chrg_id);
    $c.util.getComponent('ipt_apctNm').setValue(result.chrg_nm);
    $c.util.getComponent('ipt_jobposNm').setValue(result.jobpos_nm);
    $c.util.getComponent('ipt_belngInstNm').setValue(result.belng_inst_nm);
    $c.util.getComponent('ipt_belngDepNm').setValue(result.belng_dep_nm);
    scwin.setTelNo(result.tel_no);
    scwin.setCellphoneNo(result.cellphone_no);
    scwin.setEmail(result.email);
    scwin.setFaxNo(result.fax_no);
};

/**
 * @method
 * @name getBdchrgInfo
 * @description get Bdchrg Info 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getBdchrgInfo = async function () {
    const r = await scwin.tx_fn_GetBdchrgInfo();
    try {
        scwin.getBdchrgInfoDone.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
